  public boolean returnBook(final String bookTitle, final Date today)
  {
    if (bookTitle == null || bookTitle.isEmpty())
    {
      return false;
    }

    BorrowRecord target = null;
    for (BorrowRecord br : getBorrowRecords())
    {
      Book book = br.getBook();
      if (book != null && bookTitle.equals(book.getTitle()))
      {
        target = br;
        break;
      }
    }
    if (target == null)
    {
      return false;
    }

    if (target.isOverdue(today))
    {
      return false;
    }

    getBorrowRecords().remove(target);
    return true;
  }

